package net.civeira.phylax.feature.notification.smtpoutboundconfig.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.notification.smtpoutboundconfig.domain.SmtpOutboundConfig;
import net.civeira.phylax.feature.notification.smtpoutboundconfig.domain.valueobject.HostVO;

class HostValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of host of smtp outbound config")
  void test_host_value_holder_assign_plain_value() {
    Object holder = new Object();
    HostValueHolder<Object> value = new HostValueHolder<>(holder);
    Assertions.assertSame(holder, value.host("one"), "Setters must return the holder");
    Assertions.assertTrue(value.getHostValue().isPresent(), "The plain value must be stored");
    Assertions.assertEquals("one", value.getHost().orElse(null),
        "The plain value must be recovered");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of host of smtp outbound config")
  void test_host_value_holder_assign_value_object() {
    Object holder = new Object();
    HostValueHolder<Object> value = new HostValueHolder<>(holder);
    HostVO vo = HostVO.from("one");
    Assertions.assertFalse(value.getHostValue().isPresent(), "A new holder must be empty");
    Assertions.assertSame(holder, value.host(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getHostValue().orElseThrow());
    Assertions.assertSame(holder, value.host(Optional.empty()));
    Assertions.assertFalse(value.getHostValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.host(Optional.of(vo)));
    Assertions.assertSame(vo, value.getHostValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of host of smtp outbound config against the original")
  void test_host_value_holder_read() {
    Object holder = new Object();
    HostValueHolder<Object> value = new HostValueHolder<>(holder);
    HostVO vo = HostVO.from("one");
    HostVO other = HostVO.from("one");
    SmtpOutboundConfig original = Mockito.mock(SmtpOutboundConfig.class);
    Mockito.when(original.getHostValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readHost(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNull(value.readHost(Optional.empty(), fails),
        "Without value and original there is no result");
    Assertions.assertFalse(fails.isEmpty(), "A required value must be reported as missing");
    value.host(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readHost(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readHost(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of host of smtp outbound config")
  void test_host_value_holder_unset() {
    Object holder = new Object();
    HostValueHolder<Object> value = new HostValueHolder<>(holder);
    HostVO vo = HostVO.from("one");
    value.host(vo);
    Assertions.assertSame(holder, value.unsetHostIfMatches("host_other"));
    Assertions.assertTrue(value.getHostValue().isPresent(), "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetHostIfMatches("host"));
    Assertions.assertFalse(value.getHostValue().isPresent(), "The field name must clear the value");
    value.host(vo);
    Assertions.assertSame(holder, value.unsetHost());
    Assertions.assertFalse(value.getHostValue().isPresent(), "Unset must clear the value");
  }
}
